    #[test]
    fn runtime_deopt_guard_miss_rejects_replay_unsafe_operands() {
        assert!(
            runtime_jit_deopt_guard_operand_replay_safe(&name_expr(test_name("x"))),
            "plain local loads should be replay-safe guard operands"
        );
        assert!(
            !runtime_jit_deopt_guard_operand_replay_safe(&InstrBlockPy::Tuple(Tuple::new(vec![
                name_expr(test_name("x")),
            ]))),
            "guard miss deopt should reject operands that could repeat side effects"
        );
        let typed_load = InstrTyped::Load(Load::<InstrTyped>::new(test_name("x")));
        assert!(
            runtime_jit_typed_deopt_guard_operand_replay_safe(&typed_load),
            "plain typed local loads should be replay-safe guard operands"
        );
        let typed_tuple = InstrTyped::Tuple(Tuple::<InstrTyped>::new(Vec::new()));
        assert!(
            !runtime_jit_typed_deopt_guard_operand_replay_safe(&typed_tuple),
            "typed guard miss deopt should reject operands that could repeat side effects"
        );
        let take = InstrTyped::TakeOperand(soac_core::block_py::TakeOperand::new(test_name("x")));
        assert!(!runtime_jit_typed_deopt_guard_operand_replay_safe(&take));
        let global = InstrTyped::Load(Load::<InstrTyped>::new(ResolvedName {
            id: "guarded_global".into(),
            location: NameLocation::global(0),
        }));
        assert!(
            super::super::deopt::typed_nested_guard_misses_can_resume_before_instr(
                &InstrTyped::Tuple(Tuple::new(vec![global.clone(), take.clone()])),
            )
        );
        assert!(
            !super::super::deopt::typed_nested_guard_misses_can_resume_before_instr(
                &InstrTyped::Tuple(Tuple::new(vec![take, global])),
            ),
            "a guard after a consuming read cannot restart before that read"
        );
    }

