    #[test]
    fn runtime_typed_v3_pipeline_bypasses_serialized_v3_artifacts_in_verify_mode() {
        if crate::run_test_in_isolated_process_if_needed(
            module_path!(),
            "runtime_typed_v3_pipeline_bypasses_serialized_v3_artifacts_in_verify_mode",
        ) {
            return;
        }
        let _guard = crate::python_runtime_test_lock().lock().unwrap();
        crate::initialize_test_python();
        Python::attach(|py| {
            let soac_work_dir = fresh_test_work_dir("runtime-typed-v3-identity");
            let _work_dir = EnvVarGuard::set_os("SOAC_WORK_DIR", soac_work_dir.as_os_str());
            let _opt_mode = set_opt_mode("verify");
            let module_name = "runtime_typed_v3_identity_test";
            let module_name_gen = ModuleNameGen::new(0);
            let function = with_single_test_block(
                test_function_in_module(&module_name_gen, "target"),
                vec![],
                ret_term(none_expr()),
            );
            let module = test_module(module_name_gen, vec![function]);
            let shared_state =
                crate::module_type::build_shared_state_for_testing(py, module, module_name, "")
                    .expect("shared state should build");

            let profile = SpecializationProfile::from_runtime_state_with_session(
                Some(shared_state.as_ref()),
                None,
            )
            .expect("typed-v3 runtime pipeline should not require serialized v3 artifacts");
            assert!(
                profile.counter_dump_path.is_none(),
                "typed-v3 runtime should not enable legacy profile evidence fallback"
            );
            assert!(profile.opt_v3_emitted_direct_calls.is_empty());
            assert!(profile.opt_v3_emitted_exact_list_items.is_empty());
            assert!(profile.opt_v3_emitted_indexed_fields.is_empty());
            assert!(profile.opt_v3_emitted_indexed_globals.is_empty());
            assert!(profile.opt_v3_exact_int_branch_artifacts.is_empty());
            assert!(!profile.behavior_change_indexed_stores);
            assert!(!profile.guard_miss_deopt);

            let module_plan =
                optimize_blockpy(&shared_state.lowered_module, None, &typed_v3_env_config())
                    .expect("typed-v3 runtime should lower BlockPyModuleShape to typed JIT");
            assert_eq!(module_plan.module.callable_defs.len(), 1);
            assert_eq!(
                module_plan.module.module_name_gen.module_id(),
                shared_state.lowered_module.module_name_gen.module_id()
            );
        });
    }

    #[test]
    fn runtime_typed_v3_pipeline_emits_direct_calls_from_raw_profile_evidence() {
        if crate::run_test_in_isolated_process_if_needed(
            module_path!(),
            "runtime_typed_v3_pipeline_emits_direct_calls_from_raw_profile_evidence",
        ) {
            return;
        }
        let _guard = crate::python_runtime_test_lock().lock().unwrap();
        crate::initialize_test_python();
        Python::attach(|py| {
            let soac_work_dir = fresh_test_work_dir("runtime-typed-v3-direct-call");
            let _work_dir = EnvVarGuard::set_os("SOAC_WORK_DIR", soac_work_dir.as_os_str());
            let _opt_mode = set_opt_mode("verify");

            let module_name = "runtime_typed_v3_direct_call_test";
            let module_name_gen = ModuleNameGen::new(0);
            let mut callee_function = test_function_in_module(&module_name_gen, "callee");
            callee_function.params.params.push(Param {
                name: "x".into(),
                kind: ParamKind::Any,
                has_default: false,
            });
            callee_function = with_single_test_block(
                callee_function,
                vec![],
                ret_term(name_expr(test_local_name("x", 0))),
            );
            set_stack_slots(&mut callee_function, &["x"]);

            let mut caller_function = test_function_in_module(&module_name_gen, "caller");
            caller_function.params.params.extend([
                Param {
                    name: "fn".into(),
                    kind: ParamKind::Any,
                    has_default: false,
                },
                Param {
                    name: "x".into(),
                    kind: ParamKind::Any,
                    has_default: false,
                },
            ]);
            let caller_block_label = caller_function.name_gen.next_block_name();
            let call_instr_id = InstrId::new(1);
            caller_function = with_test_blocks(
                caller_function,
                vec![BlockPyBlock {
                    label: caller_block_label,
                    body: vec![assign_stmt(
                        test_local_name("y", 2),
                        with_instr_id(
                            op_expr(Call::new(
                                name_expr(test_local_name("fn", 0)),
                                vec![CallArgPositional::Positional(name_expr(test_local_name(
                                    "x", 1,
                                )))],
                                Vec::<CallArgKeyword<InstrBlockPy>>::new(),
                            )),
                            call_instr_id,
                        ),
                    )],
                    term: ret_term(name_expr(test_local_name("y", 2))),
                    params: vec![],
                    exc_edge: None,
                    extra: Default::default(),
                }],
            );
            set_stack_slots(&mut caller_function, &["fn", "x", "y"]);

            let caller_id = caller_function.function_id;
            let callee_id = callee_function.function_id;
            write_test_counter_dump(
                soac_work_dir.join("profile.bin").as_path(),
                &CounterDumpRecord {
                    source_hash: 0,
                    module_name: module_name.to_string(),
                    package_name: None,
                    rows: vec![
                        CounterDumpRow {
                            counter_id: 0,
                            scope: "this".to_string(),
                            kind: "call_hot_targets".to_string(),
                            site_kind: "runtime".to_string(),
                            function_id: Some(caller_id),
                            current_function_id: Some(caller_id),
                            instr_id: Some(call_instr_id),
                            function_qualname: Some(caller_function.names.qualname.clone()),
                            block_label: None,
                            value: 1,
                            branch_values: Vec::new(),
                            observed_value: Some(callee_id.to_packed_runtime_u64()),
                            max_overcount: Some(0),
                        },
                        CounterDumpRow {
                            counter_id: 1,
                            scope: "this".to_string(),
                            kind: "function_seen".to_string(),
                            site_kind: "runtime".to_string(),
                            function_id: Some(callee_id),
                            current_function_id: Some(callee_id),
                            instr_id: None,
                            function_qualname: Some(callee_function.names.qualname.clone()),
                            block_label: None,
                            value: 1,
                            branch_values: Vec::new(),
                            observed_value: None,
                            max_overcount: Some(0),
                        },
                    ],
                    module_keys: Vec::new(),
                    type_keys: Vec::new(),
                    type_table: Vec::new(),
                },
            );

            let mut module = test_module(module_name_gen, vec![callee_function, caller_function]);
            define_module_call_target_counters(&mut module);
            let shared_state =
                crate::module_type::build_shared_state_for_testing(py, module, module_name, "")
                    .expect("shared state should build");

            let profile = SpecializationProfile::from_runtime_state_with_session(
                Some(shared_state.as_ref()),
                None,
            )
            .expect("typed-v3 runtime should plan direct calls from raw profile evidence");
            assert_eq!(
                profile.counter_dump_path.as_deref(),
                Some(soac_work_dir.join("profile.bin").as_path()),
                "typed-v3 direct-call planning should retain the raw profile evidence path"
            );
            let direct_calls = profile
                .opt_v3_emitted_direct_calls
                .get(&caller_id)
                .and_then(|calls| calls.get(&call_instr_id))
                .expect("typed-v3 runtime should retain the profiled direct-call candidate");
            assert_eq!(direct_calls[0].target, callee_id);
            assert_eq!(
                direct_calls[0].body.kind,
                CallBodyKind::Inline,
                "the raw v3 planner can still record that inline won the body cost model"
            );

            let module_plan = optimize_blockpy(
                &shared_state.lowered_module,
                Some(&profile),
                &typed_v3_env_config(),
            )
            .expect("typed-v3 runtime should lower the cached pre-opt module to typed JIT");
            let planned_caller = module_plan
                .module
                .callable_defs
                .iter()
                .find(|function| function.function_id == caller_id)
                .expect("planned module should include caller");
            assert_eq!(
                profile
                    .typed_inline_direct_calls(caller_id)
                    .get(&call_instr_id)
                    .map(Vec::len),
                Some(1),
                "typed-v3 should preserve inline-winning v3 body decisions for typed inlining"
            );

            let guarded_callable_calls = count_typed_instrs(planned_caller, |expr| {
                matches!(expr, InstrTyped::GuardedCallableCallTyped(_))
            });
            let generic_typed_calls = count_typed_instrs(planned_caller, |expr| {
                matches!(expr, InstrTyped::CallTyped(_))
            });
            let direct_call_guard_tests = planned_caller
                .blocks
                .iter()
                .filter(|block| {
                    matches!(
                        &block.term,
                        BlockTerm::IfTerm(term)
                            if matches!(term.test, InstrTyped::DirectCallGuardTest(_))
                    )
                })
                .count();
            assert_eq!(
                guarded_callable_calls, 0,
                "inline-winning typed-v3 direct calls should be expanded into typed CFG instead of a local guarded call expression"
            );
            assert_eq!(
                direct_call_guard_tests, 1,
                "typed-v3 inlining should expose the direct-call guard as typed CFG"
            );
            assert!(
                planned_caller.blocks.iter().any(|block| {
                    matches!(
                        &block.term,
                        BlockTerm::IfTerm(term)
                            if matches!(term.test, InstrTyped::DirectCallGuardTest(_))
                                && term.test.guard_miss_deopt_enabled()
                    )
                }),
                "typed-v3 inlining should mark the exposed direct-call guard for deopt"
            );
            assert_eq!(
                generic_typed_calls, 1,
                "typed-v3 inlining should keep a generic fallback call"
            );

            let original_caller = shared_state
                .lowered_module
                .callable_defs
                .iter()
                .find(|function| function.function_id == caller_id)
                .expect("shared state should include original caller");
            let mut reservation_typed_caller =
                lower_blockpy_function_to_typed(original_caller.clone());
            apply_profile_typed_plans_to_typed_function(
                &mut reservation_typed_caller,
                Some(&profile),
            )
            .expect("reservation planning should still predeclare typed call imports");
            lower_typed_function_call_access_plan_instrs(&mut reservation_typed_caller);
            assert_ne!(
                reservation_typed_caller.blocks.len(),
                planned_caller.blocks.len(),
                "inline typed-v3 module rewrites can change the CFG after reservation predeclaration"
            );
            prepare_specialized_typed_function(planned_caller, None, &module_plan.value_facts)
                .expect("worker codegen should use the post-rewrite module-plan function body");
            let stale_result = prepare_specialized_typed_function(
                planned_caller,
                Some(&reservation_typed_caller),
                &module_plan.value_facts,
            );
            assert!(
                stale_result.is_err(),
                "stale reservation-time function should not override module-plan body"
            );

            let compile_session = crate::session::CompileSession::new();
            let mut jit_module =
                new_jit_module(&compile_session).expect("test jit module should construct");
            let planned_codegen_constants =
                crate::module_constants::ModuleCodegenConstants::collect_from_typed_module(
                    module_plan.module.as_ref(),
                );
            let module_constant_ptrs =
                placeholder_module_constant_ptrs(planned_codegen_constants.len());
            let module_constant_object_data_ids = declare_module_constant_object_data(
                &mut jit_module,
                module_plan.module.as_ref(),
                module_constant_ptrs.as_slice(),
            )
            .expect("module constant object data should declare");
            let (counter_slots_by_id, scalar_counter_data_id, top_value_counter_data_id) =
                define_test_counter_storage(
                    &mut jit_module,
                    &shared_state.lowered_module,
                    module_plan.module.counter_defs.as_slice(),
                );
            let blocks = vec![std::ptr::null_mut::<c_void>(); planned_caller.blocks.len()];
            let built = build_cranelift_run_bb_specialized_function(
                &mut jit_module,
                blocks.as_slice(),
                module_plan.module.as_ref(),
                planned_caller,
                &module_plan.value_facts,
                module_plan
                    .locals
                    .function(planned_caller.function_id)
                    .expect("planned caller should have JIT locals"),
                module_plan
                    .deopt_resume
                    .function(planned_caller.function_id)
                    .expect("planned caller should have deopt resume data"),
                &planned_codegen_constants,
                module_plan.module.counter_defs.as_slice(),
                module_constant_object_data_ids.as_slice(),
                counter_slots_by_id.as_ref(),
                scalar_counter_data_id,
                top_value_counter_data_id,
                &compile_session,
                Some(shared_state.as_ref()),
                None,
                None,
                BuildSpecializedFunctionOptions::default(),
            )
            .expect("inlined typed direct-call guard should compile");
            assert_guard_miss_deopts_without_local_fallback(
                &built,
                &[
                    DP_JIT_PY_CALL_POSITIONAL_THREE_IMPORT.symbol,
                    PY_SOAC_VECTORCALL_CONTEXT_IMPORT.symbol,
                ],
                "inlined typed direct-call guard",
            );
        });
    }

    #[test]
    fn runtime_typed_v3_pipeline_inlines_cross_module_direct_calls() {
        if crate::run_test_in_isolated_process_if_needed(
            module_path!(),
            "runtime_typed_v3_pipeline_inlines_cross_module_direct_calls",
        ) {
            return;
        }
        let _guard = crate::python_runtime_test_lock().lock().unwrap();
        crate::initialize_test_python();
        Python::attach(|py| {
            let soac_work_dir = fresh_test_work_dir("runtime-typed-v3-cross-module-inline");
            let _work_dir = EnvVarGuard::set_os("SOAC_WORK_DIR", soac_work_dir.as_os_str());
            let _opt_mode = set_opt_mode("verify");

            let caller_module_name = "runtime_typed_v3_cross_module_inline_caller";
            let callee_module_name = "runtime_typed_v3_cross_module_inline_callee";
            let caller_module_name_gen = ModuleNameGen::new(37);
            let callee_module_name_gen = ModuleNameGen::new(38);

            let mut callee_function = test_function_in_module(&callee_module_name_gen, "callee");
            callee_function.params.params.push(Param {
                name: "x".into(),
                kind: ParamKind::Any,
                has_default: false,
            });
            callee_function = with_single_test_block(
                callee_function,
                vec![],
                ret_term(name_expr(test_local_name("x", 0))),
            );
            set_stack_slots(&mut callee_function, &["x"]);

            let mut caller_function = test_function_in_module(&caller_module_name_gen, "caller");
            caller_function.params.params.extend([
                Param {
                    name: "fn".into(),
                    kind: ParamKind::Any,
                    has_default: false,
                },
                Param {
                    name: "x".into(),
                    kind: ParamKind::Any,
                    has_default: false,
                },
            ]);
            let caller_block_label = caller_function.name_gen.next_block_name();
            let call_instr_id = InstrId::new(1);
            caller_function = with_test_blocks(
                caller_function,
                vec![BlockPyBlock {
                    label: caller_block_label,
                    body: vec![assign_stmt(
                        test_local_name("y", 2),
                        with_instr_id(
                            op_expr(Call::new(
                                name_expr(test_local_name("fn", 0)),
                                vec![CallArgPositional::Positional(name_expr(test_local_name(
                                    "x", 1,
                                )))],
                                Vec::<CallArgKeyword<InstrBlockPy>>::new(),
                            )),
                            call_instr_id,
                        ),
                    )],
                    term: ret_term(name_expr(test_local_name("y", 2))),
                    params: vec![],
                    exc_edge: None,
                    extra: Default::default(),
                }],
            );
            set_stack_slots(&mut caller_function, &["fn", "x", "y"]);

            let caller_id = caller_function.function_id;
            let callee_id = callee_function.function_id;
            write_test_counter_dump(
                soac_work_dir.join("profile.bin").as_path(),
                &CounterDumpRecord {
                    source_hash: 0,
                    module_name: caller_module_name.to_string(),
                    package_name: None,
                    rows: vec![CounterDumpRow {
                        counter_id: 0,
                        scope: "this".to_string(),
                        kind: "call_hot_targets".to_string(),
                        site_kind: "runtime".to_string(),
                        function_id: Some(caller_id),
                        current_function_id: Some(caller_id),
                        instr_id: Some(call_instr_id),
                        function_qualname: Some(caller_function.names.qualname.clone()),
                        block_label: None,
                        value: 1,
                        branch_values: Vec::new(),
                        observed_value: Some(callee_id.to_packed_runtime_u64()),
                        max_overcount: Some(0),
                    }],
                    module_keys: Vec::new(),
                    type_keys: Vec::new(),
                    type_table: Vec::new(),
                },
            );

            let caller_module = test_module(caller_module_name_gen, vec![caller_function]);
            let callee_module = test_module(callee_module_name_gen, vec![callee_function]);
            let caller_shared_state = crate::module_type::build_shared_state_for_testing(
                py,
                caller_module,
                caller_module_name,
                "",
            )
            .expect("caller shared state should build");
            let callee_shared_state = crate::module_type::build_shared_state_for_testing(
                py,
                callee_module,
                callee_module_name,
                "",
            )
            .expect("callee shared state should build");
            let compile_session = crate::session::CompileSession::new();
            compile_session
                .retain_shared_module_state_for_inspection(caller_shared_state.clone())
                .expect("caller module should be retained for planning");
            compile_session
                .retain_shared_module_state_for_inspection(callee_shared_state.clone())
                .expect("callee module should be retained for planning");

            let profile = SpecializationProfile::from_runtime_state_with_session(
                Some(caller_shared_state.as_ref()),
                Some(&compile_session),
            )
            .expect("typed-v3 runtime should plan cross-module direct calls from raw evidence");
            let direct_calls = profile
                .opt_v3_emitted_direct_calls
                .get(&caller_id)
                .and_then(|calls| calls.get(&call_instr_id))
                .expect("typed-v3 runtime should retain the profiled cross-module candidate");
            assert_eq!(direct_calls[0].target, callee_id);
            assert_eq!(
                direct_calls[0].body.kind,
                CallBodyKind::Inline,
                "cross-module direct calls should keep inline body decisions when remappable"
            );

            let module_plan = optimize_blockpy_for_shared_state(
                caller_shared_state.as_ref(),
                Some(&compile_session),
                Some(&profile),
                compile_session
                    .env_config()
                    .expect("compile session env config should resolve"),
            )
            .expect("typed-v3 runtime should lower caller with external callee bodies visible");
            let cached_module_plan = optimize_blockpy_for_shared_state(
                caller_shared_state.as_ref(),
                Some(&compile_session),
                Some(&profile),
                compile_session
                    .env_config()
                    .expect("compile session env config should resolve"),
            )
            .expect("typed-v3 runtime should reuse cached shared-state plans");
            assert!(
                std::sync::Arc::ptr_eq(&module_plan, &cached_module_plan),
                "verify/apply shared-state planning should reuse the cached typed module plan"
            );
            let planned_caller = module_plan
                .module
                .callable_defs
                .iter()
                .find(|function| function.function_id == caller_id)
                .expect("planned module should include caller");
            assert_eq!(
                count_typed_instrs(planned_caller, |expr| {
                    matches!(expr, InstrTyped::GuardedCallableCallTyped(_))
                }),
                0,
                "cross-module inline-winning direct calls should not remain guarded call expressions"
            );
            assert_eq!(
                planned_caller
                    .blocks
                    .iter()
                    .filter(|block| {
                        matches!(
                            &block.term,
                            BlockTerm::IfTerm(term)
                                if matches!(term.test, InstrTyped::DirectCallGuardTest(_))
                        )
                    })
                    .count(),
                1,
                "cross-module typed-v3 inlining should expose a direct-call guard CFG edge"
            );
        });
    }

    #[test]
    fn runtime_typed_v3_retains_capsule_activations_in_closed_iterator_pipelines() {
        if crate::run_test_in_isolated_process_if_needed(
            module_path!(),
            "runtime_typed_v3_retains_capsule_activations_in_closed_iterator_pipelines",
        ) {
            return;
        }
        let _guard = crate::python_runtime_test_lock().lock().unwrap();
        crate::initialize_test_python();
        Python::attach(|py| {
            let env_config =
                typed_v3_env_config().with_specialization_mode(Some(SpecializationMode::Verify));
            let runtime_source = r#"
def list_from_iter(value):
    result = []
    iterator = iter(value)
    while True:
        try:
            item = next(iterator)
            result.append(item)
        except StopIteration:
            return result

def tuple_from_iter(value):
    result = []
    iterator = iter(value)
    while True:
        try:
            item = next(iterator)
            result.append(item)
        except StopIteration:
            return tuple(result)

def map_from_iter(function, iterable):
    return __soac_map_iterator(function, iter(iterable))

def __soac_map_iterator(function, iterator):
    while True:
        try:
            item = next(iterator)
        except StopIteration:
            return
        try:
            mapped = function(item)
        except StopIteration:
            return
        yield mapped

def filter_from_iter(function, iterable):
    return __soac_filter_iterator(function, iter(iterable))

def __soac_filter_iterator(function, iterator):
    while True:
        try:
            item = next(iterator)
        except StopIteration:
            return
        if function is None:
            predicate = item
        else:
            try:
                predicate = function(item)
            except StopIteration:
                return
        try:
            if predicate:
                yield item
        except StopIteration:
            return

NO_DEFAULT = object()

def _is_generator_closed(owner):
    return bool(load_preserved_state(owner._preserved_values, owner._closed_slot))

def _reraise_control_flow(exc):
    raise exc

class ClosureGenerator:
    def __iter__(self):
        return self

    def __next__(self):
        return self.send(None)

    def send(self, value):
        if _is_generator_closed(self):
            raise StopIteration
        try:
            return resume_generator(
                self._resume_function,
                self,
                self._preserved_values,
                value,
                NO_DEFAULT,
            )
        except BaseException as exc:
            _reraise_control_flow(exc)
"#;
            let user_source = r#"
def convert(value):
    return value * 3 + 1

def keep(value):
    return value % 2 == 0

def collect(count):
    mapped = list(map(convert, (value for value in range(count))))
    filtered = tuple(filter(keep, (value for value in range(count))))
    return mapped, filtered
"#;

            let runtime_lowered = soac_lowering::lower_python_to_blockpy_with_tracker_and_options(
                runtime_source,
                ModuleNameGen::new(41),
                soac_core::pass_tracker::RecordingPassTracker::new(),
                soac_lowering::LoweringOptions {
                    runtime_names_as_globals: true,
                    ..Default::default()
                },
            )
            .expect("closed-pipeline runtime source should lower")
            .blockpy_module;
            let user_lowered = soac_lowering::lower_python_to_blockpy_with_tracker_and_options(
                user_source,
                ModuleNameGen::new(42),
                soac_core::pass_tracker::RecordingPassTracker::new(),
                soac_lowering::LoweringOptions {
                    runtime_names_as_globals: false,
                    ..Default::default()
                },
            )
            .expect("closed-pipeline user source should lower")
            .blockpy_module;
            let collect_id = user_lowered
                .callable_defs
                .iter()
                .find(|function| function.names.qualname == "collect")
                .map(|function| function.function_id)
                .expect("user source should define collect");
            let runtime_shared_state = crate::module_type::build_shared_state_for_testing(
                py,
                runtime_lowered,
                "soac.runtime",
                "soac",
            )
            .expect("closed-pipeline runtime shared state should build");
            let user_module_name = "runtime_typed_v3_closed_iterator_pipeline_user";
            let user_shared_state = crate::module_type::build_shared_state_for_testing(
                py,
                user_lowered,
                user_module_name,
                "",
            )
            .expect("closed-pipeline user shared state should build");
            let compile_session = crate::session::CompileSession::new();
            compile_session
                .retain_shared_module_state_for_inspection(runtime_shared_state)
                .expect("runtime module should be retained for closed-pipeline planning");
            compile_session
                .retain_shared_module_state_for_inspection(user_shared_state.clone())
                .expect("user module should be retained for closed-pipeline planning");

            let profile = SpecializationProfile {
                module_name: Some(user_module_name),
                counter_dump_path: None,
                direct_call_emission_scope: DirectCallEmissionScope::AllDirectCallCandidates,
                opt_v3_emitted_direct_calls: HashMap::new(),
                opt_v3_emitted_exact_list_items: HashMap::new(),
                opt_v3_emitted_indexed_fields: HashMap::new(),
                opt_v3_emitted_indexed_globals: HashMap::new(),
                opt_v3_exact_int_branch_artifacts: HashMap::new(),
                behavior_change_indexed_stores: false,
                profiled_cold_blocks: false,
                guard_miss_deopt: false,
            };
            let module_plan = optimize_blockpy_for_shared_state(
                user_shared_state.as_ref(),
                Some(&compile_session),
                Some(&profile),
                &env_config,
            )
            .expect("closed map/filter/genexpr pipeline should have a validated typed plan");
            let planned_collect = module_plan
                .module
                .callable_defs
                .iter()
                .find(|function| function.function_id == collect_id)
                .expect("planned user module should include collect");

            #[derive(Default)]
            struct RetainedSuspendedActivations {
                generator_instance_plans: usize,
                generator_resume_plans: usize,
                native_iterator_pipelines: usize,
                generator_closures: usize,
                preserved_references: usize,
            }

            impl RetainedSuspendedActivations {
                fn record_name(&mut self, name: &ResolvedName) {
                    if name.preserved_location().is_some()
                        || name.cell_location().is_some_and(CellLocation::is_preserved)
                    {
                        self.preserved_references += 1;
                    }
                }
            }

            impl Visit<InstrTyped> for RetainedSuspendedActivations {
                fn visit_instr(&mut self, expr: &InstrTyped) {
                    self.generator_instance_plans +=
                        usize::from(expr.generator_instance_plan().is_some());
                    self.generator_resume_plans +=
                        usize::from(expr.generator_resume_plan().is_some());
                    self.native_iterator_pipelines +=
                        usize::from(expr.native_iterator_pipeline_plan().is_some());
                    match expr {
                        InstrTyped::MakeFunctionWithClosure(make_function)
                            if make_function.kind == FunctionKind::Generator =>
                        {
                            self.generator_closures += 1;
                        }
                        InstrTyped::Load(load) => self.record_name(&load.name),
                        InstrTyped::Store(store) => self.record_name(&store.name),
                        InstrTyped::Del(del) => self.record_name(&del.name),
                        InstrTyped::CellRef(cell_ref) if cell_ref.location.is_preserved() => {
                            self.preserved_references += 1;
                        }
                        _ => {}
                    }
                    expr.visit_children(self);
                }
            }

            let mut residuals = RetainedSuspendedActivations::default();
            residuals.visit_fn(planned_collect);
            assert!(
                residuals.generator_instance_plans > 0,
                "an immediately consumed generator still needs its own activation",
            );
            assert_eq!(
                residuals.native_iterator_pipelines, 2,
                "both closed wrappers use the validated native-input template",
            );
            assert_eq!(
                residuals.generator_resume_plans, 0,
                "native tp_iternext keeps resume and handled state inside the original generator",
            );
            assert!(
                residuals.generator_closures >= 2,
                "both source genexprs retain factories for their distinct capsules",
            );
            assert_eq!(
                residuals.preserved_references, 0,
                "retaining resume calls must not move capsule storage into an ordinary caller",
            );
            for layout in planned_collect
                .storage_layout
                .iter()
                .chain(planned_collect.public_storage_layout.iter())
            {
                assert!(
                    layout.preserved_slots.is_empty(),
                    "closed pipeline should not retain preserved storage slots: {:?}",
                    layout.preserved_slots,
                );
            }
        });
    }

    #[test]
    fn runtime_typed_v3_pipeline_inlines_static_runtime_range_calls() {
        if crate::run_test_in_isolated_process_if_needed(
            module_path!(),
            "runtime_typed_v3_pipeline_inlines_static_runtime_range_calls",
        ) {
            return;
        }
        let _guard = crate::python_runtime_test_lock().lock().unwrap();
        crate::initialize_test_python();
        Python::attach(|py| {
            let caller_module_name = "runtime_typed_v3_static_runtime_range_caller";
            let caller_module_name_gen = ModuleNameGen::new(39);

            let mut caller_function = test_function_in_module(&caller_module_name_gen, "caller");
            caller_function.params.params.push(Param {
                name: "value".into(),
                kind: ParamKind::Any,
                has_default: false,
            });
            let caller_block_label = caller_function.name_gen.next_block_name();
            let call_instr_id = InstrId::new(1);
            caller_function = with_test_blocks(
                caller_function,
                vec![BlockPyBlock {
                    label: caller_block_label,
                    body: vec![assign_stmt(
                        test_local_name("obj", 1),
                        with_instr_id(
                            op_expr(Call::new(
                                name_expr(test_runtime_name("range")),
                                vec![CallArgPositional::Positional(name_expr(test_local_name(
                                    "value", 0,
                                )))],
                                Vec::<CallArgKeyword<InstrBlockPy>>::new(),
                            )),
                            call_instr_id,
                        ),
                    )],
                    term: ret_term(name_expr(test_local_name("obj", 1))),
                    params: vec![],
                    exc_edge: None,
                    extra: Default::default(),
                }],
            );
            set_stack_slots(&mut caller_function, &["value", "obj"]);
            let caller_id = caller_function.function_id;

            let runtime_lowered = soac_lowering::lower_python_to_blockpy_with_tracker_and_options(
                "class range:\n    def __init__(self, *args):\n        argc = len(args)\n        if argc != 1:\n            raise TypeError\n        self.value = args[0]\n",
                ModuleNameGen::new(40),
                soac_core::pass_tracker::RecordingPassTracker::new(),
                soac_lowering::LoweringOptions {
                    runtime_names_as_globals: true,
                    ..Default::default()
                },
            )
            .expect("runtime source should lower");
            let runtime_shared_state = crate::module_type::build_shared_state_for_testing(
                py,
                runtime_lowered.blockpy_module,
                "soac.runtime",
                "",
            )
            .expect("runtime shared state should build");
            let caller_shared_state = crate::module_type::build_shared_state_for_testing(
                py,
                test_module(caller_module_name_gen, vec![caller_function]),
                caller_module_name,
                "",
            )
            .expect("caller shared state should build");
            let compile_session = crate::session::CompileSession::new();
            compile_session
                .retain_shared_module_state_for_inspection(runtime_shared_state)
                .expect("runtime module should be retained for planning");
            compile_session
                .retain_shared_module_state_for_inspection(caller_shared_state.clone())
                .expect("caller module should be retained for planning");

            let profile = SpecializationProfile {
                module_name: Some(caller_module_name),
                counter_dump_path: None,
                direct_call_emission_scope: DirectCallEmissionScope::AllDirectCallCandidates,
                opt_v3_emitted_direct_calls: HashMap::new(),
                opt_v3_emitted_exact_list_items: HashMap::new(),
                opt_v3_emitted_indexed_fields: HashMap::new(),
                opt_v3_emitted_indexed_globals: HashMap::new(),
                opt_v3_exact_int_branch_artifacts: HashMap::new(),
                behavior_change_indexed_stores: false,
                profiled_cold_blocks: false,
                guard_miss_deopt: false,
            };
            let module_plan = optimize_blockpy_for_shared_state(
                caller_shared_state.as_ref(),
                Some(&compile_session),
                Some(&profile),
                &typed_v3_env_config(),
            )
            .expect("typed-v3 runtime should inline the statically known range target");
            let planned_caller = module_plan
                .module
                .callable_defs
                .iter()
                .find(|function| function.function_id == caller_id)
                .expect("planned module should include caller");
            assert_eq!(
                count_typed_instrs(planned_caller, |expr| {
                    matches!(expr, InstrTyped::GuardedCallableCallTyped(_))
                }),
                0,
                "static runtime range calls should inline through the ordinary typed direct-call path"
            );
            assert_eq!(
                count_typed_instrs(planned_caller, |expr| matches!(expr, InstrTyped::Tuple(_))),
                0,
                "inlined static runtime range calls should scalarize compiler-created packed rest tuples"
            );
            assert_eq!(
                planned_caller
                    .blocks
                    .iter()
                    .filter(|block| {
                        matches!(
                            &block.term,
                            BlockTerm::IfTerm(term)
                                if matches!(term.test, InstrTyped::DirectCallGuardTest(_))
                        )
                    })
                    .count(),
                0,
                "static runtime range and nested IterRange inlining should avoid guard CFG edges"
            );
        });
    }

