    #[test]
    fn runtime_typed_v3_inline_remaps_callee_exact_list_item_access_plans() {
        let module_name = "runtime_typed_v3_inline_exact_list_item_plan_test";
        let module_name_gen = ModuleNameGen::new(0);
        let mut callee_function = test_function_in_module(&module_name_gen, "replace_first");
        callee_function.params = ParamSpec {
            params: vec![
                test_param("items", ParamKind::Any, false),
                test_param("index", ParamKind::Any, false),
            ],
        };
        let callee_block_label = callee_function.name_gen.next_block_name();
        let callee_setitem_instr_id = InstrId::new(0);
        let callee_getitem_instr_id = InstrId::new(1);
        callee_function.blocks = vec![BlockPyBlock {
            label: callee_block_label,
            body: vec![with_instr_id(
                op_expr(SetItem::new(
                    name_expr(test_name("items")),
                    name_expr(test_name("index")),
                    none_expr(),
                )),
                callee_setitem_instr_id,
            )],
            term: ret_term(with_instr_id(
                op_expr(GetItem::new(
                    name_expr(test_name("items")),
                    name_expr(test_name("index")),
                )),
                callee_getitem_instr_id,
            )),
            params: Vec::new(),
            exc_edge: None,
            extra: Default::default(),
        }];
        set_stack_slots(&mut callee_function, &["items", "index"]);

        let mut caller_function = test_function_in_module(&module_name_gen, "caller");
        caller_function.params = ParamSpec {
            params: vec![
                test_param("fn", ParamKind::Any, false),
                test_param("items", ParamKind::Any, false),
                test_param("index", ParamKind::Any, false),
            ],
        };
        let caller_block_label = caller_function.name_gen.next_block_name();
        let caller_call_instr_id = InstrId::new(10);
        caller_function.blocks = vec![BlockPyBlock {
            label: caller_block_label,
            body: vec![with_instr_id(
                op_expr(Call::new(
                    name_expr(test_local_name("fn", 0)),
                    vec![
                        CallArgPositional::Positional(name_expr(test_local_name("items", 1))),
                        CallArgPositional::Positional(name_expr(test_local_name("index", 2))),
                    ],
                    Vec::<CallArgKeyword<InstrBlockPy>>::new(),
                )),
                caller_call_instr_id,
            )],
            term: ret_term(none_expr()),
            params: Vec::new(),
            exc_edge: None,
            extra: Default::default(),
        }];
        set_stack_slots(&mut caller_function, &["fn", "items", "index"]);

        let callee_id = callee_function.function_id;
        let caller_id = caller_function.function_id;
        let module = test_module(module_name_gen, vec![callee_function, caller_function]);
        let exact_list_item_plan = |source, access| OptV3ExactListItemAccessPlan {
            source,
            access,
            shape: PlanV3ExactListItemShape::ExactListExactInt,
            guard: PlanV3ExactListItemGuardKind::ExactListExactCompactIntInBounds,
            fallback: PlanV3ExactListItemFallbackKind::OriginalItemAccess,
        };
        let profile = SpecializationProfile {
            module_name: Some(module_name),
            counter_dump_path: None,
            direct_call_emission_scope: DirectCallEmissionScope::AllDirectCallCandidates,
            opt_v3_emitted_direct_calls: HashMap::from([(
                caller_id,
                HashMap::from([(
                    caller_call_instr_id,
                    vec![ResolvedV3DirectCallPlan {
                        source: caller_call_instr_id,
                        target: callee_id,
                        callee: soac_ir_typed::plan_v3::DirectCallCallee::Function,
                        arg_plan: TypedDirectCallArgPlan {
                            sources: vec![
                                TypedDirectCallArgSource::Provided(0),
                                TypedDirectCallArgSource::Provided(1),
                            ],
                        },
                        body: CallBodyPlan {
                            kind: CallBodyKind::Inline,
                            cost: Cost::default(),
                            inline_target: None,
                            reason: "test inlines the effect-only call body".to_string(),
                        },
                        reason: "profiled direct call".to_string(),
                    }],
                )]),
            )]),
            opt_v3_emitted_exact_list_items: HashMap::from([(
                callee_id,
                HashMap::from([
                    (
                        callee_setitem_instr_id,
                        exact_list_item_plan(
                            callee_setitem_instr_id,
                            PlanV3ExactListItemAccessKind::Set,
                        ),
                    ),
                    (
                        callee_getitem_instr_id,
                        exact_list_item_plan(
                            callee_getitem_instr_id,
                            PlanV3ExactListItemAccessKind::Get,
                        ),
                    ),
                ]),
            )]),
            opt_v3_emitted_indexed_fields: HashMap::new(),
            opt_v3_emitted_indexed_globals: HashMap::new(),
            opt_v3_exact_int_branch_artifacts: HashMap::new(),
            behavior_change_indexed_stores: false,
            profiled_cold_blocks: false,
            guard_miss_deopt: false,
        };

        let module_plan = optimize_blockpy(&module, Some(&profile), &typed_v3_env_config())
            .expect("typed-v3 module plan should inline and remap callee item plans");
        let planned_caller = module_plan
            .module
            .callable_defs
            .iter()
            .find(|function| function.function_id == caller_id)
            .expect("planned module should include caller");
        assert_eq!(
            count_typed_instrs(planned_caller, |expr| {
                matches!(expr, InstrTyped::GuardedCallableCallTyped(_))
            }),
            0,
            "inline-winning effect-only calls should be expanded into typed CFG"
        );
        assert_eq!(
            planned_caller
                .blocks
                .iter()
                .filter(|block| {
                    matches!(
                        &block.term,
                        BlockTerm::IfTerm(term)
                            if matches!(term.test, InstrTyped::DirectCallGuardTest(_))
                    )
                })
                .count(),
            1,
            "the inlined call should keep a direct-call guard in the caller CFG"
        );

        let mut setitem_plans = Vec::new();
        let mut getitem_plans = Vec::new();
        struct Collector<'a> {
            setitem_plans: &'a mut Vec<(
                InstrId,
                InstrId,
                PlanV3ExactListItemAccessKind,
                Option<(RuntimeFunctionId, InstrId)>,
            )>,
            getitem_plans: &'a mut Vec<(
                InstrId,
                InstrId,
                PlanV3ExactListItemAccessKind,
                Option<(RuntimeFunctionId, InstrId)>,
            )>,
        }
        impl Visit<InstrTyped> for Collector<'_> {
            fn visit_instr(&mut self, expr: &InstrTyped) {
                match expr {
                    InstrTyped::SetItem(op) => {
                        if let Some(plan) = op.extra().exact_list_item_access_plan() {
                            self.setitem_plans.push((
                                op.semantic_instr_id(),
                                plan.instr_id,
                                plan.access,
                                plan.counter_source
                                    .map(|source| (source.function_id, source.instr_id)),
                            ));
                        }
                    }
                    InstrTyped::GetItem(op) => {
                        if let Some(plan) = op.extra().exact_list_item_access_plan() {
                            self.getitem_plans.push((
                                op.semantic_instr_id(),
                                plan.instr_id,
                                plan.access,
                                plan.counter_source
                                    .map(|source| (source.function_id, source.instr_id)),
                            ));
                        }
                    }
                    _ => {}
                }
                expr.visit_children(self);
            }
        }
        let mut collector = Collector {
            setitem_plans: &mut setitem_plans,
            getitem_plans: &mut getitem_plans,
        };
        collector.visit_fn(planned_caller);
        assert_eq!(setitem_plans.len(), 1);
        assert_eq!(getitem_plans.len(), 1);

        let (remapped_setitem_instr_id, setitem_source, setitem_access, setitem_counter_source) =
            &setitem_plans[0];
        assert_ne!(*remapped_setitem_instr_id, callee_setitem_instr_id);
        assert_eq!(*setitem_source, *remapped_setitem_instr_id);
        assert_eq!(*setitem_access, PlanV3ExactListItemAccessKind::Set);
        assert_eq!(
            *setitem_counter_source,
            Some((callee_id, callee_setitem_instr_id))
        );

        let (remapped_getitem_instr_id, getitem_source, getitem_access, getitem_counter_source) =
            &getitem_plans[0];
        assert_ne!(*remapped_getitem_instr_id, callee_getitem_instr_id);
        assert_eq!(*getitem_source, *remapped_getitem_instr_id);
        assert_eq!(*getitem_access, PlanV3ExactListItemAccessKind::Get);
        assert_eq!(
            *getitem_counter_source,
            Some((callee_id, callee_getitem_instr_id))
        );
    }

    #[test]
    fn runtime_typed_v3_inline_remaps_callee_indexed_field_access_plans_from_live_owner_namespace()
    {
        if crate::run_test_in_isolated_process_if_needed(
            module_path!(),
            "runtime_typed_v3_inline_remaps_callee_indexed_field_access_plans_from_live_owner_namespace",
        ) {
            return;
        }
        let _guard = crate::python_runtime_test_lock().lock().unwrap();
        crate::initialize_test_python();
        Python::attach(|py| {
            let owner_module = PyModule::from_code(
                py,
                c"
class Point:
    pass
",
                c"field_type_test.py",
                c"field_type_test",
            )
            .expect("owner module should execute");
            let sys = PyModule::import(py, "sys").expect("sys should import");
            let modules = sys
                .getattr("modules")
                .expect("sys.modules should exist")
                .cast_into::<pyo3::types::PyDict>()
                .expect("sys.modules should be a dict");
            modules
                .set_item("field_type_test", owner_module.as_any())
                .expect("owner module should be registered");
            // Keep the real namespace alive through resolution. A raw registry
            // address is not ownership; the separate namespace-decline test
            // covers removal without weakening this positive remapping case.

            let module_name = "runtime_typed_v3_inline_indexed_field_plan_test";
            let module_name_gen = ModuleNameGen::new(0);
            let mut constants = TestConstantPool::default();

            let mut callee_function = test_function_in_module(&module_name_gen, "read_point");
            callee_function.params = ParamSpec {
                params: vec![test_param("point", ParamKind::Any, false)],
            };
            let callee_block_label = callee_function.name_gen.next_block_name();
            let callee_getattr_instr_id = InstrId::new(1);
            callee_function.blocks = vec![BlockPyBlock {
                label: callee_block_label,
                body: Vec::new(),
                term: ret_term(with_instr_id(
                    op_expr(GetAttr::new(
                        name_expr(test_name("point")),
                        constants.string_expr("x"),
                    )),
                    callee_getattr_instr_id,
                )),
                params: Vec::new(),
                exc_edge: None,
                extra: Default::default(),
            }];
            set_stack_slots(&mut callee_function, &["point"]);

            let mut caller_function = test_function_in_module(&module_name_gen, "caller");
            caller_function.params = ParamSpec {
                params: vec![
                    test_param("fn", ParamKind::Any, false),
                    test_param("point", ParamKind::Any, false),
                ],
            };
            let caller_block_label = caller_function.name_gen.next_block_name();
            let caller_call_instr_id = InstrId::new(10);
            caller_function.blocks = vec![BlockPyBlock {
                label: caller_block_label,
                body: vec![assign_stmt(
                    test_local_name("out", 2),
                    with_instr_id(
                        op_expr(Call::new(
                            name_expr(test_local_name("fn", 0)),
                            vec![CallArgPositional::Positional(name_expr(test_local_name(
                                "point", 1,
                            )))],
                            Vec::<CallArgKeyword<InstrBlockPy>>::new(),
                        )),
                        caller_call_instr_id,
                    ),
                )],
                term: ret_term(name_expr(test_local_name("out", 2))),
                params: Vec::new(),
                exc_edge: None,
                extra: Default::default(),
            }];
            set_stack_slots(&mut caller_function, &["fn", "point", "out"]);

            let callee_id = callee_function.function_id;
            let caller_id = caller_function.function_id;
            let mut module = test_module(module_name_gen, vec![callee_function, caller_function]);
            module.module_constants = constants.module_constants;
            let profile = SpecializationProfile {
                module_name: Some(module_name),
                counter_dump_path: None,
                direct_call_emission_scope: DirectCallEmissionScope::AllDirectCallCandidates,
                opt_v3_emitted_direct_calls: HashMap::from([(
                    caller_id,
                    HashMap::from([(
                        caller_call_instr_id,
                        vec![ResolvedV3DirectCallPlan {
                            source: caller_call_instr_id,
                            target: callee_id,
                            callee: soac_ir_typed::plan_v3::DirectCallCallee::Function,
                            arg_plan: TypedDirectCallArgPlan {
                                sources: vec![TypedDirectCallArgSource::Provided(0)],
                            },
                            body: CallBodyPlan {
                                kind: CallBodyKind::Inline,
                                cost: Cost::default(),
                                inline_target: None,
                                reason: "test inlines the field load callee".to_string(),
                            },
                            reason: "profiled direct call".to_string(),
                        }],
                    )]),
                )]),
                opt_v3_emitted_exact_list_items: HashMap::new(),
                opt_v3_emitted_indexed_fields: HashMap::from([(
                    callee_id,
                    HashMap::from([(
                        callee_getattr_instr_id,
                        vec![OptV3IndexedFieldAccessPlan {
                            access: IndexedFieldAccessKind::Load,
                            guard: MechanicalIndexedFieldGuard {
                                kind: IndexedFieldGuardKind::OwnerTypeVersionAndFieldIndex,
                                owner_type: IndexedFieldOwnerType {
                                    module_name: "field_type_test".to_string(),
                                    qualname: "Point".to_string(),
                                },
                                attr_name: "x".to_string(),
                                expected_index: 0,
                            },
                            fallback: IndexedFieldFallbackKind::OriginalAttrAccess,
                        }],
                    )]),
                )]),
                opt_v3_emitted_indexed_globals: HashMap::new(),
                opt_v3_exact_int_branch_artifacts: HashMap::new(),
                behavior_change_indexed_stores: false,
                profiled_cold_blocks: false,
                guard_miss_deopt: false,
            };

            let module_plan = optimize_blockpy(&module, Some(&profile), &typed_v3_env_config())
                .expect("typed-v3 module plan should inline and remap callee field plans");
            let planned_caller = module_plan
                .module
                .callable_defs
                .iter()
                .find(|function| function.function_id == caller_id)
                .expect("planned module should include caller");

            let mut field_plans = Vec::new();
            struct Collector<'a> {
                field_plans: &'a mut Vec<(InstrId, usize)>,
            }
            impl Visit<InstrTyped> for Collector<'_> {
                fn visit_instr(&mut self, expr: &InstrTyped) {
                    if let InstrTyped::GetAttrTyped(op) = expr
                        && let TypedAttrAccessPlan::IndexedField { source, guards, .. } = &op.access
                    {
                        assert_eq!(*source, TypedIndexedFieldPlanSource::OptimizationPlanV3);
                        self.field_plans
                            .push((op.semantic_instr_id(), guards.len()));
                    }
                    expr.visit_children(self);
                }
            }
            Collector {
                field_plans: &mut field_plans,
            }
            .visit_fn(planned_caller);

            assert_eq!(field_plans.len(), 1);
            assert_ne!(field_plans[0].0, callee_getattr_instr_id);
            assert_eq!(field_plans[0].1, 1);
            modules
                .del_item("field_type_test")
                .expect("owner module should be removed after the remapping check");
        });
    }

    #[test]
    fn runtime_typed_v3_inline_remaps_callee_exact_int_plans() {
        let module_name = "runtime_typed_v3_inline_exact_int_plan_test";
        let module_name_gen = ModuleNameGen::new(0);
        let mut constants = TestConstantPool::default();

        let mut callee_function = test_function_in_module(&module_name_gen, "add_with_local");
        callee_function.params = ParamSpec {
            params: vec![
                test_param("a", ParamKind::Any, false),
                test_param("b", ParamKind::Any, false),
            ],
        };
        let callee_block_label = callee_function.name_gen.next_block_name();
        let callee_tmp_add_instr_id = InstrId::new(2);
        let callee_return_add_instr_id = InstrId::new(5);
        callee_function.blocks = vec![BlockPyBlock {
            label: callee_block_label,
            body: vec![assign_stmt(
                test_local_name("tmp", 2),
                with_instr_id(
                    op_expr(BinOp::new(
                        BinOpKind::Add,
                        name_expr(test_name("a")),
                        constants.int_expr(2),
                    )),
                    callee_tmp_add_instr_id,
                ),
            )],
            term: ret_term(with_instr_id(
                op_expr(BinOp::new(
                    BinOpKind::Add,
                    name_expr(test_local_name("b", 1)),
                    name_expr(test_local_name("tmp", 2)),
                )),
                callee_return_add_instr_id,
            )),
            params: Vec::new(),
            exc_edge: None,
            extra: Default::default(),
        }];
        set_stack_slots(&mut callee_function, &["a", "b", "tmp"]);

        let mut caller_function = test_function_in_module(&module_name_gen, "caller");
        caller_function.params = ParamSpec {
            params: vec![
                test_param("fn", ParamKind::Any, false),
                test_param("x", ParamKind::Any, false),
                test_param("y", ParamKind::Any, false),
            ],
        };
        let caller_block_label = caller_function.name_gen.next_block_name();
        let caller_call_instr_id = InstrId::new(10);
        caller_function.blocks = vec![BlockPyBlock {
            label: caller_block_label,
            body: vec![assign_stmt(
                test_local_name("out", 3),
                with_instr_id(
                    op_expr(Call::new(
                        name_expr(test_local_name("fn", 0)),
                        vec![
                            CallArgPositional::Positional(name_expr(test_local_name("x", 1))),
                            CallArgPositional::Positional(name_expr(test_local_name("y", 2))),
                        ],
                        Vec::<CallArgKeyword<InstrBlockPy>>::new(),
                    )),
                    caller_call_instr_id,
                ),
            )],
            term: ret_term(name_expr(test_local_name("out", 3))),
            params: Vec::new(),
            exc_edge: None,
            extra: Default::default(),
        }];
        set_stack_slots(&mut caller_function, &["fn", "x", "y", "out"]);

        let callee_id = callee_function.function_id;
        let caller_id = caller_function.function_id;
        let mut module = test_module(module_name_gen, vec![callee_function, caller_function]);
        module.module_constants = constants.module_constants;
        let callee_function = module
            .callable_defs
            .iter()
            .find(|function| function.function_id == callee_id)
            .expect("module should include callee")
            .clone();

        let exact_int_shape = soac_opt::operator_specialization::pack_binary_shape(
            soac_opt::operator_specialization::ExactTypeTag::Int,
            soac_opt::operator_specialization::ExactTypeTag::Int,
        );
        let mut evidence = FunctionProfileEvidence::default();
        evidence
            .operator_specializations
            .insert(callee_tmp_add_instr_id, vec![exact_int_shape]);
        evidence
            .operator_specializations
            .insert(callee_return_add_instr_id, vec![exact_int_shape]);
        let artifacts = plan_and_emit_function_exact_int_branches_v3_with_module_constants(
            &AlternativeCatalog::default_v3(),
            ModulePlanIdentity {
                module_name: module_name.to_string(),
                source_hash: 0,
                cache_identity: "test-cache".to_string(),
            },
            FunctionPlanIdentity {
                function: SerializedFunctionId::new(
                    SerializedModuleId::new(0),
                    callee_function.function_id.local_function_id(),
                ),
                debug_name: Some(callee_function.names.qualname.clone()),
            },
            &callee_function,
            &evidence,
            module.module_constants.as_slice(),
        )
        .expect("exact-int v3 artifacts should plan callee arithmetic");
        let profile = SpecializationProfile {
            module_name: Some(module_name),
            counter_dump_path: None,
            direct_call_emission_scope: DirectCallEmissionScope::AllDirectCallCandidates,
            opt_v3_emitted_direct_calls: HashMap::from([(
                caller_id,
                HashMap::from([(
                    caller_call_instr_id,
                    vec![ResolvedV3DirectCallPlan {
                        source: caller_call_instr_id,
                        target: callee_id,
                        callee: soac_ir_typed::plan_v3::DirectCallCallee::Function,
                        arg_plan: TypedDirectCallArgPlan {
                            sources: vec![
                                TypedDirectCallArgSource::Provided(0),
                                TypedDirectCallArgSource::Provided(1),
                            ],
                        },
                        body: CallBodyPlan {
                            kind: CallBodyKind::Inline,
                            cost: Cost::default(),
                            inline_target: None,
                            reason: "test inlines the exact-int callee body".to_string(),
                        },
                        reason: "profiled direct call".to_string(),
                    }],
                )]),
            )]),
            opt_v3_emitted_exact_list_items: HashMap::new(),
            opt_v3_emitted_indexed_fields: HashMap::new(),
            opt_v3_emitted_indexed_globals: HashMap::new(),
            opt_v3_exact_int_branch_artifacts: HashMap::from([(
                callee_id,
                std::sync::Arc::new(artifacts),
            )]),
            behavior_change_indexed_stores: false,
            profiled_cold_blocks: false,
            guard_miss_deopt: false,
        };

        let module_plan = optimize_blockpy(&module, Some(&profile), &typed_v3_env_config())
            .expect("typed-v3 module plan should inline and remap callee exact-int plans");
        let planned_caller = module_plan
            .module
            .callable_defs
            .iter()
            .find(|function| function.function_id == caller_id)
            .expect("planned module should include caller");

        struct Collector {
            return_plans: Vec<(InstrId, InstrId, Vec<String>, Option<InstrId>)>,
        }
        impl Visit<InstrTyped> for Collector {
            fn visit_instr(&mut self, expr: &InstrTyped) {
                if let Some(plan) = expr
                    .typed_extra()
                    .and_then(|extra| extra.exact_int_return_plan())
                {
                    let input_names = plan
                        .hot_plan
                        .inputs
                        .iter()
                        .filter_map(|input| match &input.source {
                            RegionInputSource::FunctionParam {
                                name: Some(name), ..
                            } => Some(name.clone()),
                            _ => None,
                        })
                        .collect::<Vec<_>>();
                    self.return_plans.push((
                        expr.try_semantic_instr_id()
                            .expect("planned exact-int expression should have an instruction id"),
                        plan.instr_id,
                        input_names,
                        plan.hot_region.exits.first().and_then(|exit| exit.source),
                    ));
                }
                expr.visit_children(self);
            }
        }
        let mut collector = Collector {
            return_plans: Vec::new(),
        };
        collector.visit_fn(planned_caller);
        collector
            .return_plans
            .sort_by_key(|(_, plan_instr_id, _, _)| *plan_instr_id);
        collector
            .return_plans
            .dedup_by_key(|(_, plan_instr_id, _, _)| *plan_instr_id);
        assert_eq!(
            collector.return_plans.len(),
            2,
            "both callee arithmetic sites should keep exact-int return plans after inlining"
        );
        let mut all_input_names = Vec::new();
        for (expr_instr_id, plan_instr_id, input_names, hot_exit_source) in &collector.return_plans
        {
            assert_eq!(
                expr_instr_id, plan_instr_id,
                "remapped exact-int plan should use the caller instruction id"
            );
            assert_ne!(*plan_instr_id, callee_tmp_add_instr_id);
            assert_ne!(*plan_instr_id, callee_return_add_instr_id);
            assert_eq!(
                *hot_exit_source,
                Some(*plan_instr_id),
                "mechanical exact-int exit source should be remapped with the plan"
            );
            assert!(
                input_names
                    .iter()
                    .all(|name| !matches!(name.as_str(), "a" | "b" | "tmp")),
                "exact-int region inputs should not keep callee-local names: {input_names:?}"
            );
            all_input_names.extend(input_names.iter().cloned());
        }
        assert!(
            all_input_names
                .iter()
                .any(|name| name.starts_with("_dp_typed_inline_arg")),
            "callee parameter inputs should be remapped to caller argument temps: {all_input_names:?}"
        );
        assert!(
            all_input_names.iter().any(|name| {
                name.starts_with("_dp_typed_inline_") && !name.starts_with("_dp_typed_inline_arg")
            }),
            "callee local inputs should be remapped to caller inline locals: {all_input_names:?}"
        );
        prepare_specialized_typed_function(planned_caller, None, &module_plan.value_facts)
            .expect("remapped exact-int plans should be valid for typed codegen");
    }

    #[test]
    fn runtime_typed_v3_module_plan_carries_exact_int_selection_shapes() {
        let module_name = "runtime_typed_v3_exact_int_plan_test";
        let module_name_gen = ModuleNameGen::new(0);
        let mut function = test_function_in_module(&module_name_gen, "branch_and_add");
        function.params = ParamSpec {
            params: vec![
                test_param("a", ParamKind::Any, false),
                test_param("b", ParamKind::Any, false),
            ],
        };
        let entry_label = function.name_gen.next_block_name();
        let then_label = function.name_gen.next_block_name();
        let else_label = function.name_gen.next_block_name();
        let branch_add_instr_id = InstrId::new(2);
        let compare_instr_id = InstrId::new(4);
        let return_add_instr_id = InstrId::new(7);
        let mut constants = TestConstantPool::default();
        function.blocks = vec![
            BlockPyBlock {
                label: entry_label,
                body: Vec::new(),
                term: BlockTerm::IfTerm(soac_core::block_py::TermIf {
                    test: with_instr_id(
                        op_expr(BinOp::new(
                            BinOpKind::Gt,
                            with_instr_id(
                                op_expr(BinOp::new(
                                    BinOpKind::Add,
                                    with_instr_id(name_expr(test_name("a")), InstrId::new(0)),
                                    with_instr_id(
                                        name_expr(test_local_name("b", 1)),
                                        InstrId::new(1),
                                    ),
                                )),
                                branch_add_instr_id,
                            ),
                            with_instr_id(constants.int_expr(0), InstrId::new(3)),
                        )),
                        compare_instr_id,
                    ),
                    then_label,
                    else_label,
                }),
                params: Vec::new(),
                exc_edge: None,
                extra: Default::default(),
            },
            BlockPyBlock {
                label: then_label,
                body: Vec::new(),
                term: ret_term(with_instr_id(
                    op_expr(BinOp::new(
                        BinOpKind::Add,
                        with_instr_id(name_expr(test_name("a")), InstrId::new(5)),
                        with_instr_id(name_expr(test_local_name("b", 1)), InstrId::new(6)),
                    )),
                    return_add_instr_id,
                )),
                params: Vec::new(),
                exc_edge: None,
                extra: Default::default(),
            },
            BlockPyBlock {
                label: else_label,
                body: Vec::new(),
                term: ret_term(constants.int_expr(0)),
                params: Vec::new(),
                exc_edge: None,
                extra: Default::default(),
            },
        ];
        set_stack_slots(&mut function, &["a", "b"]);
        let function_id = function.function_id;
        let mut module = test_module(module_name_gen, vec![function]);
        module.module_constants = constants.module_constants;
        let function = module.callable_defs[0].clone();
        let exact_int_shape = soac_opt::operator_specialization::pack_binary_shape(
            soac_opt::operator_specialization::ExactTypeTag::Int,
            soac_opt::operator_specialization::ExactTypeTag::Int,
        );
        let mut evidence = FunctionProfileEvidence::default();
        evidence
            .operator_specializations
            .insert(branch_add_instr_id, vec![exact_int_shape]);
        evidence
            .operator_specializations
            .insert(return_add_instr_id, vec![exact_int_shape]);
        let artifacts = plan_and_emit_function_exact_int_branches_v3_with_module_constants(
            &AlternativeCatalog::default_v3(),
            ModulePlanIdentity {
                module_name: module_name.to_string(),
                source_hash: 0,
                cache_identity: "test-cache".to_string(),
            },
            FunctionPlanIdentity {
                function: SerializedFunctionId::new(
                    SerializedModuleId::new(0),
                    function.function_id.local_function_id(),
                ),
                debug_name: Some(function.names.qualname.clone()),
            },
            &function,
            &evidence,
            module.module_constants.as_slice(),
        )
        .expect("exact-int v3 artifacts should plan for branch and return sources");
        let profile = SpecializationProfile {
            module_name: Some(module_name),
            counter_dump_path: None,
            direct_call_emission_scope: DirectCallEmissionScope::AllDirectCallCandidates,
            opt_v3_emitted_direct_calls: HashMap::new(),
            opt_v3_emitted_exact_list_items: HashMap::new(),
            opt_v3_emitted_indexed_fields: HashMap::new(),
            opt_v3_emitted_indexed_globals: HashMap::new(),
            opt_v3_exact_int_branch_artifacts: HashMap::from([(
                function_id,
                std::sync::Arc::new(artifacts),
            )]),
            behavior_change_indexed_stores: false,
            profiled_cold_blocks: false,
            guard_miss_deopt: false,
        };

        let module_plan = optimize_blockpy(&module, Some(&profile), &typed_v3_env_config())
            .expect("typed-v3 module plan should attach exact-int selections");
        let planned_function = module_plan
            .module
            .callable_defs
            .iter()
            .find(|function| function.function_id == function_id)
            .expect("planned module should include branch_and_add");
        let BlockTerm::IfTerm(if_term) = &planned_function.blocks[0].term else {
            panic!("entry block should remain a typed if term");
        };
        let branch_plan = if_term
            .test
            .typed_extra()
            .and_then(|extra| extra.exact_int_branch_plan())
            .expect("typed-v3 module plan should carry exact-int branch selection");
        assert_eq!(
            branch_plan.source,
            TypedExactIntPlanSource::OptimizationPlanV3
        );
        assert_eq!(branch_plan.instr_id, compare_instr_id);
        assert_eq!(branch_plan.hot_plan.id, branch_plan.hot_region.region);
        assert_eq!(
            branch_plan
                .hot_region
                .exits
                .first()
                .and_then(|exit| exit.source),
            Some(compare_instr_id)
        );

        let BlockTerm::Return(return_value) = &planned_function.blocks[1].term else {
            panic!("then block should remain a typed return");
        };
        let return_plan = return_value
            .typed_extra()
            .and_then(|extra| extra.exact_int_return_plan())
            .expect("typed-v3 module plan should carry exact-int return selection");
        assert_eq!(
            return_plan.source,
            TypedExactIntPlanSource::OptimizationPlanV3
        );
        assert_eq!(return_plan.instr_id, return_add_instr_id);
        assert_eq!(return_plan.hot_plan.id, return_plan.hot_region.region);
        assert_eq!(
            return_plan
                .hot_region
                .exits
                .first()
                .and_then(|exit| exit.source),
            Some(return_add_instr_id)
        );
    }

    #[test]
    fn runtime_typed_v3_exact_int_cell_inputs_compile_from_resolved_storage() {
        let module_name = "exact_int_cell_storage";
        let names = ModuleNameGen::new(0);
        let mut function = test_function_in_module(&names, "captured_add");
        function.params.params = vec![test_param("value", ParamKind::Any, false)];
        let add_source = InstrId::new(2);
        function = with_single_test_block(
            function,
            Vec::new(),
            ret_term(with_instr_id(
                op_expr(BinOp::new(
                    BinOpKind::Add,
                    with_instr_id(
                        op_expr(
                            Load::new(test_closure_cell_name("offset", 0)).with_cell_binding(Some(
                                CellLoadBinding {
                                    logical_name: "offset".into(),
                                    kind: CellBindingKind::Capture,
                                },
                            )),
                        ),
                        InstrId::new(0),
                    ),
                    with_instr_id(name_expr(test_local_name("value", 0)), InstrId::new(1)),
                )),
                add_source,
            )),
        );
        set_stack_slots(&mut function, &["value"]);
        function.storage_layout.as_mut().unwrap().freevars = vec![ClosureSlot {
            logical_name: "offset".into(),
            storage_name: "_dp_cell_offset".into(),
            init: ClosureInit::InheritedCapture,
        }];
        let function_id = function.function_id;
        let module = test_module(names, vec![function.clone()]);
        let mut evidence = FunctionProfileEvidence::default();
        evidence.operator_specializations.insert(
            add_source,
            vec![soac_opt::operator_specialization::pack_binary_shape(
                soac_opt::operator_specialization::ExactTypeTag::Int,
                soac_opt::operator_specialization::ExactTypeTag::Int,
            )],
        );
        let artifacts = plan_and_emit_function_exact_int_branches_v3_with_module_constants(
            &AlternativeCatalog::default_v3(),
            ModulePlanIdentity {
                module_name: module_name.into(),
                source_hash: 0,
                cache_identity: "test".into(),
            },
            FunctionPlanIdentity {
                function: SerializedFunctionId::new(
                    SerializedModuleId::new(0),
                    function_id.local_function_id(),
                ),
                debug_name: Some(function.names.qualname.clone()),
            },
            &function,
            &evidence,
            &module.module_constants,
        )
        .expect("a resolved closure load must remain eligible for exact-int arithmetic");
        let profile = SpecializationProfile {
            module_name: Some(module_name),
            counter_dump_path: None,
            direct_call_emission_scope: DirectCallEmissionScope::AllDirectCallCandidates,
            opt_v3_emitted_direct_calls: HashMap::new(),
            opt_v3_emitted_exact_list_items: HashMap::new(),
            opt_v3_emitted_indexed_fields: HashMap::new(),
            opt_v3_emitted_indexed_globals: HashMap::new(),
            opt_v3_exact_int_branch_artifacts: HashMap::from([(
                function_id,
                std::sync::Arc::new(artifacts),
            )]),
            behavior_change_indexed_stores: false,
            profiled_cold_blocks: false,
            guard_miss_deopt: false,
        };
        let module_plan =
            optimize_blockpy(&module, Some(&profile), &typed_v3_env_config()).unwrap();
        let planned = module_plan
            .module
            .callable_defs
            .iter()
            .find(|candidate| candidate.function_id == function_id)
            .unwrap()
            .clone();
        struct CellInputs(usize);
        impl Visit<InstrTyped> for CellInputs {
            fn visit_instr(&mut self, instr: &InstrTyped) {
                if let Some(plan) = instr
                    .typed_extra()
                    .and_then(|extra| extra.exact_int_return_plan())
                {
                    for region in [&plan.hot_plan, &plan.fallback_plan] {
                        assert!(matches!(
                            &region.inputs[0].source,
                            RegionInputSource::CellValue { source, name, binding }
                                if *source == InstrId::new(0)
                                    && name.cell_location() == Some(CellLocation::Closure(0))
                                    && binding.kind == CellBindingKind::Capture
                        ));
                        self.0 += 1;
                    }
                }
                instr.visit_children(self);
            }
        }
        let mut inputs = CellInputs(0);
        inputs.visit_fn(&planned);
        assert_eq!(
            inputs.0, 2,
            "both hot and generic regions must retain the cell binding"
        );
        let constants =
            crate::module_constants::ModuleCodegenConstants::collect_from_module(&module);
        let session = crate::session::CompileSession::new_with_env_config(SoacEnvConfig::default());
        let mut jit = new_jit_module(&session).unwrap();
        let pointers = placeholder_module_constant_ptrs(constants.len());
        let data = declare_module_constant_object_data(&mut jit, &module, &pointers).unwrap();
        let (slots, scalar_data, top_data) =
            define_test_counter_storage(&mut jit, &module, &module.counter_defs);
        let built = build_test_cranelift_run_bb_specialized_function(
            &mut jit,
            &[1usize as ObjPtr],
            &module,
            &function,
            &constants,
            &module.counter_defs,
            &data,
            &slots,
            scalar_data,
            top_data,
            &session,
            None,
            None,
            None,
            BuildSpecializedFunctionOptions {
                planned_typed_function: Some(planned),
                ..BuildSpecializedFunctionOptions::default()
            },
        )
        .expect("cell input lowering must load a cell value, not an unavailable local offset");
        let loads = import_user_names_for_symbols(&built, &["dp_jit_load_cell"]);
        assert_eq!(
            count_direct_calls_to_runtime_helpers(&built.ctx.func, &loads),
            2
        );
    }

